# -*- coding: utf-8 -*-
"""
create_video_story_sheet.py
インフルエンサー向け動画ストーリー構成シートを作成する
"""

import sys
import io

sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8")

from google.oauth2 import service_account
from googleapiclient.discovery import build

SHEET_ID = "1vBVvQZ-3p0vz8rQAQye8L-0AvmUiuuxW929ZV3PyRgM"
NEW_SHEET = "\u30a4\u30f3\u30d5\u30eb\u5411\u3051\u52d5\u753b\u30b9\u30c8\u30fc\u30ea\u30fc"

creds = service_account.Credentials.from_service_account_file(
    "credentials/google_service_account.json",
    scopes=["https://www.googleapis.com/auth/spreadsheets"],
)
service = build("sheets", "v4", credentials=creds)

# 既存シート確認・削除
meta = service.spreadsheets().get(spreadsheetId=SHEET_ID).execute()
for s in meta["sheets"]:
    if s["properties"]["title"] == NEW_SHEET:
        service.spreadsheets().batchUpdate(
            spreadsheetId=SHEET_ID,
            body={"requests": [{"deleteSheet": {"sheetId": s["properties"]["sheetId"]}}]},
        ).execute()
        print("deleted:", NEW_SHEET)

# 新シート作成
resp = service.spreadsheets().batchUpdate(
    spreadsheetId=SHEET_ID,
    body={"requests": [{"addSheet": {"properties": {"title": NEW_SHEET}}}]},
).execute()
new_sheet_id = resp["replies"][0]["addSheet"]["properties"]["sheetId"]
print("new sheet id:", new_sheet_id)

# 元データ取得
result = service.spreadsheets().values().get(
    spreadsheetId=SHEET_ID, range="\u52d5\u753b\u69cb\u6210\u30d1\u30bf\u30fc\u30f3"
).execute()
rows = result.get("values", [])
header = rows[0]
data = rows[1:]


def get(row, col_name):
    idx = header.index(col_name) if col_name in header else -1
    if idx == -1 or idx >= len(row):
        return ""
    return row[idx].strip()


# グループ化
patterns = {}
order = []
current_product = ""

for row in data:
    product = get(row, "\u5546\u54c1\u30b0\u30eb\u30fc\u30d7")
    if product:
        current_product = product.replace("\n", " ")
    category = get(row, "\u30ab\u30c6\u30b4\u30ea\u30fc").replace("\n", " ")
    key = category
    if key not in patterns:
        patterns[key] = {
            "product": current_product,
            "category": category,
            "appeal": get(row, "\u8a34\u6c42\u8ef8"),
            "duration": get(row, "\u63a8\u5968\u5c3a"),
            "format": get(row, "\u6295\u7a3f\u5f62\u5f0f"),
            "influencer": get(row, "\u53c2\u8003\u30a4\u30f3\u30d5\u30eb\u30a8\u30f3\u30b5\u30fc").replace("\n", " / "),
            "steps": [],
        }
        order.append(key)
    step = get(row, "\u30b9\u30c6\u30c3\u30d7")
    scene = get(row, "\u5834\u9762")
    if step:
        patterns[key]["steps"].append({"step": step, "scene": scene})
    if not patterns[key]["influencer"] and get(row, "\u53c2\u8003\u30a4\u30f3\u30d5\u30eb\u30a8\u30f3\u30b5\u30fc"):
        patterns[key]["influencer"] = get(row, "\u53c2\u8003\u30a4\u30f3\u30d5\u30eb\u30a8\u30f3\u30b5\u30fc").replace("\n", " / ")

